import { computed, Service, signal } from '@angular/core';

@Service()
export class NotificationStore {
  // Writable by every component that injects the store
  readonly items = signal<AppNotification[]>([]);
  readonly unread = computed(
    () => this.items().filter((n) => !n.read).length,
  );

  markRead(id: string) {
    const item = this.items().find((n) => n.id === id);
    // Mutates in place: same array, so unread() never recomputes
    if (item) item.read = true;
  }
}

import { computed, Service, signal } from '@angular/core';

@Service()
export class NotificationStore {
  private readonly _items = signal<readonly AppNotification[]>([]);

  // Components can read these; only the methods below write
  readonly items = this._items.asReadonly();
  readonly unread = computed(
    () => this._items().filter((n) => !n.read).length,
  );

  add(notification: AppNotification) {
    this._items.update((items) => [notification, ...items]);
  }

  markRead(id: string) {
    this._items.update((items) =>
      items.map((n) => (n.id === id ? { ...n, read: true } : n)),
    );
  }
}
